<?php require __DIR__.'/../includes/bootstrap.php';require_admin();$pageTitle='Members';$basePath='../';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)$_POST['id'];$status=$_POST['status'];$pdo->prepare('UPDATE members SET status=? WHERE id=?')->execute([$status,$id]);$pdo->prepare('UPDATE users SET is_active=? WHERE id=(SELECT user_id FROM members WHERE id=?)')->execute([$status==='active'?1:0,$id]);audit($pdo,'Changed member status','Member #'.$id.' '.$status);flash('success','Member status updated.');redirect('members.php');}$members=$pdo->query('SELECT m.*,u.username,(SELECT COUNT(*) FROM loans l WHERE l.member_id=m.id AND l.status="issued") active_loans FROM members m LEFT JOIN users u ON u.id=m.user_id ORDER BY m.id DESC')->fetchAll();require __DIR__.'/../includes/layout_top.php';?><div class="panel"><div class="panel-head"><div><h3>Registered members</h3><p>Member accounts created through self-registration or by an administrator.</p></div><span class="pill neutral"><?=count($members)?> members</span></div><div class="table-wrap"><table><thead><tr><th>Member</th><th>Member ID</th><th>Contact</th><th>Active loans</th><th>Status</th><th>Control</th></tr></thead><tbody><?php foreach($members as $m):?><tr><td><b><?=e($m['name'])?></b><small>@<?=e($m['username']??'—')?></small></td><td><?=e($m['member_code'])?></td><td><?=e($m['email'])?><small><?=e($m['phone'])?></small></td><td><?=$m['active_loans']?></td><td><span class="pill <?=$m['status']==='active'?'success':'danger'?>"><?=e($m['status'])?></span></td><td><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$m['id']?>"><select name="status"><option value="active" <?=$m['status']==='active'?'selected':''?>>Active</option><option value="inactive" <?=$m['status']==='inactive'?'selected':''?>>Inactive</option><option value="suspended" <?=$m['status']==='suspended'?'selected':''?>>Suspended</option></select><button class="btn small">Update</button></form></td></tr><?php endforeach;?><?php if(!$members):?><tr><td colspan="6" class="empty">No members registered yet.</td></tr><?php endif;?></tbody></table></div></div><?php require __DIR__.'/../includes/layout_bottom.php';?>
